const $ = (s) => document.querySelector(s);
const state = { servers: [], apps: [], databases: [], audit: [], monitoring: {}, page: 'dashboard' };

async function api(path, options = {}) {
  const isForm = options.body instanceof FormData;
  const response = await fetch(path, { ...options, headers: { ...(isForm ? {} : { 'Content-Type': 'application/json' }), ...(options.headers || {}) } });
  if (response.status === 401) { showLogin(); throw new Error('请重新登录'); }
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error || `请求失败：${response.status}`);
  return body;
}

function showLogin() { $('#app').classList.add('hidden'); $('#login').classList.remove('hidden'); }
function showApp() { $('#login').classList.add('hidden'); $('#app').classList.remove('hidden'); }
function escapeHTML(value = '') { return String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function statusText(value) { return ({ online: '在线', offline: '离线', pending: '待检测', running: '运行中', deploying: '部署中', building: '构建中', uploaded: '已上传', draft: '待部署', stopped: '已停止', failed: '失败', error: '异常', completed: '已完成' })[value] || value || '未知'; }
function ago(date) { const seconds = Math.max(0, (Date.now() - new Date(date).getTime()) / 1000); if (seconds < 60) return '刚刚'; if (seconds < 3600) return `${Math.floor(seconds/60)} 分钟前`; if (seconds < 86400) return `${Math.floor(seconds/3600)} 小时前`; return new Date(date).toLocaleDateString('zh-CN'); }
function formatBytes(value = 0) { if (value < 1024) return `${value} B`; if (value < 1048576) return `${(value/1024).toFixed(1)} KB`; if (value < 1073741824) return `${(value/1048576).toFixed(1)} MB`; return `${(value/1073741824).toFixed(2)} GB`; }
function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 2400); }

$('#login-form').addEventListener('submit', async (event) => {
  event.preventDefault(); $('#login-error').textContent = '';
  try { await api('/api/login', { method: 'POST', body: JSON.stringify({ password: $('#password').value }) }); $('#password').value = ''; showApp(); await refresh(); }
  catch (error) { $('#login-error').textContent = error.message; }
});
$('#logout').addEventListener('click', async () => { await api('/api/logout', { method: 'POST' }).catch(() => {}); showLogin(); });
$('#manage-sessions').addEventListener('click', openSessions);
$('#change-password').addEventListener('click', () => { $('#modal-form').dataset.kind = 'password'; $('#modal-eyebrow').textContent = 'SECURITY'; $('#modal-title').textContent = '修改管理员密码'; $('#modal-fields').innerHTML = `<label class="full">当前密码<input name="currentPassword" type="password" autocomplete="current-password" required></label><label class="full">新密码<input name="newPassword" type="password" autocomplete="new-password" required></label><label class="full">再次输入新密码<input name="confirmPassword" type="password" autocomplete="new-password" required></label>`; $('#modal-error').textContent = ''; $('.modal-actions').classList.remove('hidden'); $('#modal').showModal(); });

async function openSessions() {
  $('#modal-form').dataset.kind = ''; $('#modal-eyebrow').textContent = 'SECURITY'; $('#modal-title').textContent = '登录设备';
  $('#modal-fields').innerHTML = '<div class="setup-loading full"><span class="spinner"></span>正在读取登录会话…</div>'; $('#modal-error').textContent = ''; $('.modal-actions').classList.add('hidden');
  if (!$('#modal').open) $('#modal').showModal();
  try { const data = await api('/api/account/sessions'); $('#modal-fields').innerHTML = `<div class="session-list full">${data.sessions.map(item => `<article><div><strong>${item.current ? '当前设备' : '其他设备'} ${item.current ? '<span class="badge online">当前</span>' : ''}</strong><small>${escapeHTML(item.ip || '未知 IP')} · ${escapeHTML(item.userAgent || '旧版会话')}</small><small>登录：${new Date(item.createdAt).toLocaleString('zh-CN')} · 最近活动：${new Date(item.lastSeenAt).toLocaleString('zh-CN')}</small></div><button type="button" class="danger-button" data-session-revoke="${escapeHTML(item.id)}" data-current="${item.current}">${item.current ? '退出当前设备' : '远程退出'}</button></article>`).join('')}</div><p class="muted full">登录失败 5 次会自动锁定来源 IP 10 分钟。HTTPS 访问时 Cookie 会强制使用安全传输。</p>`; }
  catch (error) { $('#modal-fields').innerHTML = ''; $('#modal-error').textContent = error.message; }
}

const pages = {
  dashboard: ['基础设施概览', '添加服务器'], servers: ['托管服务器', '添加服务器'],
  apps: ['应用', '创建应用'], databases: ['数据库', '创建数据库'], activity: ['操作记录', '刷新']
};
function navigate(page) {
  if (!pages[page]) page = 'dashboard'; state.page = page;
  document.querySelectorAll('.page').forEach(el => el.classList.toggle('active', el.id === `${page}-page`));
  document.querySelectorAll('#nav a').forEach(el => el.classList.toggle('active', el.dataset.page === page));
  $('#page-title').textContent = pages[page][0]; $('#page-action').textContent = pages[page][1];
}
window.addEventListener('hashchange', () => navigate(location.hash.slice(1)));

function metric(label, value, detail) { return `<article class="metric"><small>${label}</small><strong>${value}</strong><small>${detail}</small></article>`; }
function renderDashboard(data) {
  $('#metrics').innerHTML = [metric('服务器', data.servers, `${data.onlineServers} 台在线`), metric('应用', data.apps, `${data.runningApps} 个运行中`), metric('数据库', data.databases, '持久化服务'), metric('平台状态', '正常', '控制平面可用')].join('');
  $('#server-summary').className = state.servers.length ? 'card-grid' : 'empty-state';
  $('#server-summary').innerHTML = state.servers.length ? state.servers.slice(0,3).map(serverCard).join('') : '暂无服务器，先添加一台 VPS。';
  renderAudit((data.audit || []).slice(-8), '#audit-summary');
}
function serverCard(s) { const m = state.monitoring[s.id]; return `<article class="resource-card"><div class="card-top"><div><h4>${escapeHTML(s.name)}</h4><p>${escapeHTML(s.user)}@${escapeHTML(s.host)}:${s.port} · ${s.authType === 'password' ? '密码登录' : '密钥登录'}</p></div><span class="badge ${s.status}">${escapeHTML(statusText(s.status))}</span></div><p>${s.environmentReady ? '<span class="ready-text">✓ 网站部署环境已完全就绪</span>' : s.k3sVersion ? `K3s ${escapeHTML(s.k3sVersion)} · 请检查完整环境` : '等待环境初始化'}</p><p>${m ? `CPU ${m.cpuPercent}% · 内存 ${m.memoryPercent}% · 磁盘 ${m.diskPercent}%` : s.cpu ? `${s.cpu} CPU · ${s.memoryMB} MB · ${s.diskGB} GB` : '尚未读取硬件信息'}</p><div class="card-actions"><button data-server-edit="${escapeHTML(s.id)}">编辑</button><button data-server-action="test" data-id="${escapeHTML(s.id)}">检测连接</button><button data-env-inspect="${escapeHTML(s.id)}">初始化环境</button><button data-server-action="adopt" data-id="${escapeHTML(s.id)}">扫描并接管</button><button class="danger" data-delete-type="server" data-id="${escapeHTML(s.id)}">删除</button></div></article>`; }
function serverName(id) { return state.servers.find(server => server.id === id)?.name || '未知服务器'; }
function appCard(a) { const domains = (a.domains || []).map(d => d.host).join(' · '), adopted = a.managedMode === 'adopted', stopped = a.status === 'stopped'; return `<article class="resource-card"><div class="card-top"><div><span class="server-chip">▤ ${escapeHTML(serverName(a.serverId))}</span><h4>${escapeHTML(a.name)}</h4><p>${adopted ? `${escapeHTML(a.namespace)} · 现有 K3s 服务` : escapeHTML(a.repository || a.archiveName || (a.sourceType === 'image' ? '本地归档镜像' : '本地源码'))}</p></div><span class="badge ${a.status}">${escapeHTML(statusText(a.status))}</span></div><p>${domains ? escapeHTML(domains) : '尚未绑定域名'}</p><p>${adopted ? '已无停机接管' : `${escapeHTML(a.buildType)} · 端口 ${a.port || 8080} · 自动部署${a.autoDeploy ? '已开启' : '未开启'}`}</p>${a.autoDeployError ? `<p class="error">${escapeHTML(a.autoDeployError)}</p>` : ''}<div class="card-actions">${adopted ? '' : `<button data-app-config="${escapeHTML(a.id)}">编辑配置</button>`}<button data-adopted-domains="${escapeHTML(a.id)}">编辑域名</button>${domains ? `<button data-domain-health="${escapeHTML(a.id)}">域名状态</button>` : ''}${adopted ? `<button data-app-promote="${escapeHTML(a.id)}">转为原生管理</button>` : ''}${stopped ? `<button data-app-runtime="start" data-id="${escapeHTML(a.id)}">启动</button>` : `<button data-app-runtime="restart" data-id="${escapeHTML(a.id)}">重启</button><button data-app-runtime="stop" data-id="${escapeHTML(a.id)}">停止</button>`}${adopted ? '' : `<button data-app-action="deploy" data-id="${escapeHTML(a.id)}">${a.image ? '重新构建部署' : '开始部署'}</button>`}<button data-app-runtime-log="${escapeHTML(a.id)}">运行日志</button>${!adopted ? `<button data-app-history="${escapeHTML(a.id)}">版本/回滚</button>` : ''}${a.deployLog ? `<button data-app-log="${escapeHTML(a.id)}">构建日志</button>` : ''}<button class="danger" data-delete-type="app" data-id="${escapeHTML(a.id)}">${adopted ? '移出面板' : '删除'}</button></div></article>`; }
function dbCard(d) { const adopted = d.managedMode === 'adopted', stopped = d.status === 'stopped', provisioned = Boolean(d.host); return `<article class="resource-card"><div class="card-top"><div><h4>${escapeHTML(d.name)}</h4><p>${escapeHTML(d.engine)} ${escapeHTML(d.version)}</p></div><span class="badge ${d.status}">${escapeHTML(statusText(d.status))}</span></div><p>${d.storageGB} GB 持久卷${adopted ? ' · 已独立接管' : ''}</p><p>${d.host ? `${escapeHTML(d.host)}:${d.port}` : '等待部署'}</p><div class="card-actions">${d.status === 'running' ? `<button data-db-view="${escapeHTML(d.id)}">查看数据库</button>${['postgresql','postgres'].includes(d.engine) ? `<button data-db-backups="${escapeHTML(d.id)}">备份/恢复</button>` : ''}` : ''}<button data-db-rename="${escapeHTML(d.id)}">修改名称</button>${!adopted && !provisioned ? `<button data-db-edit="${escapeHTML(d.id)}">编辑配置</button>` : ''}${provisioned ? (stopped ? `<button data-db-runtime="start" data-id="${escapeHTML(d.id)}">启动</button>` : `<button data-db-runtime="restart" data-id="${escapeHTML(d.id)}">重启</button><button data-db-runtime="stop" data-id="${escapeHTML(d.id)}">停止</button>`) : ''}${adopted ? '' : `<button data-db-action="provision" data-id="${escapeHTML(d.id)}">${provisioned ? '重新部署配置' : '开始部署'}</button>`}<button class="danger" data-delete-type="database" data-id="${escapeHTML(d.id)}">${adopted ? '移出面板' : '永久删除'}</button></div></article>`; }
function renderAudit(items, selector) { $(selector).innerHTML = items.length ? [...items].reverse().map(e => `<div class="timeline-item"><span></span><div>${escapeHTML(e.message)}<br><small class="muted">${escapeHTML(e.action)} · ${escapeHTML(e.resource || '-')}</small></div><time title="${new Date(e.createdAt).toLocaleString('zh-CN')}">${ago(e.createdAt)}</time></div>`).join('') : '<div class="empty-state">暂无符合条件的操作记录</div>'; }
function filteredAudit() { const q = ($('#audit-search')?.value || '').trim().toLowerCase(), type = $('#audit-filter')?.value || ''; return state.audit.filter(e => (!type || e.action.startsWith(`${type}.`)) && (!q || `${e.action} ${e.resource} ${e.message}`.toLowerCase().includes(q))); }
function renderFullAudit() { const items = filteredAudit(); renderAudit(items, '#audit-list'); $('#audit-count').textContent = `${items.length}/${state.audit.length} 条`; }
function renderLists() {
  $('#servers-list').innerHTML = state.servers.length ? state.servers.map(serverCard).join('') : '<div class="empty-state">尚未添加服务器</div>';
  $('#setup-server').innerHTML = state.servers.length ? state.servers.map(s => `<option value="${escapeHTML(s.id)}">${escapeHTML(s.name)} · ${escapeHTML(s.host)}</option>`).join('') : '<option value="">请先添加服务器</option>';
  const previousFilter = $('#app-server-filter').value;
  $('#app-server-filter').innerHTML = `<option value="">全部服务器（${state.apps.length}）</option>${state.servers.map(s => `<option value="${escapeHTML(s.id)}">${escapeHTML(s.name)}（${state.apps.filter(a => a.serverId === s.id).length}）</option>`).join('')}`;
  if (state.servers.some(s => s.id === previousFilter)) $('#app-server-filter').value = previousFilter;
  renderAppsByServer();
  $('#databases-list').innerHTML = state.databases.length ? state.databases.map(dbCard).join('') : '<div class="empty-state">尚未创建数据库</div>';
  renderFullAudit();
}
function renderAppsByServer() { const filter = $('#app-server-filter').value; const apps = filter ? state.apps.filter(a => a.serverId === filter) : state.apps; if (!apps.length) { $('#apps-list').innerHTML = '<div class="empty-state">该服务器尚未部署应用</div>'; return; } const groups = []; const ids = [...new Set(apps.map(a => a.serverId))]; ids.forEach(id => { const items = apps.filter(a => a.serverId === id); groups.push(`<section class="app-server-group"><div class="group-head"><div><span class="status-dot"></span><strong>${escapeHTML(serverName(id))}</strong></div><small>${items.length} 个应用</small></div><div class="card-grid">${items.map(appCard).join('')}</div></section>`); }); $('#apps-list').innerHTML = groups.join(''); }

function environmentRows(components) { return components.map(item => `<div class="component-row"><div><strong>${escapeHTML(item.name)}</strong><small>${escapeHTML(item.category)} · ${escapeHTML(item.description)}</small></div><span class="component-status ${item.installed ? 'installed' : 'missing'}">${item.installed ? `✓ 已安装${item.version ? ` · ${escapeHTML(item.version)}` : ''}` : '待安装'}</span></div>`).join(''); }
async function openEnvironment(serverId) {
  if (!serverId) { toast('请先添加并选择服务器'); return; }
  $('#modal-form').dataset.kind = ''; $('#modal-eyebrow').textContent = 'STEP 1 · ENVIRONMENT'; $('#modal-title').textContent = '正在检测服务器环境'; $('#modal-fields').innerHTML = '<div class="setup-loading full"><span class="spinner"></span>正在通过 SSH 检查已安装组件…</div>'; $('#modal-error').textContent = ''; $('.modal-actions').classList.add('hidden'); $('#modal').showModal();
  try {
    const result = await api(`/api/servers/${encodeURIComponent(serverId)}/environment`);
    $('#modal-title').textContent = '网站运行环境';
    $('#modal-fields').innerHTML = `<div class="environment-summary full"><strong>已安装 ${result.installed}/${result.total}</strong><span>${result.ready ? '环境已经就绪，可按需强制重装' : '检测到缺失组件，可一键补齐'}</span></div><div class="component-list full">${environmentRows(result.components)}</div><div class="install-actions full"><button type="button" class="primary" data-env-install="${escapeHTML(serverId)}" data-mode="skip">${result.ready ? '检查并跳过已安装项' : '一键安装缺失组件'}</button><button type="button" class="secondary" data-env-install="${escapeHTML(serverId)}" data-mode="force">强制重新安装全部</button></div><p class="muted full">默认模式会自动跳过已安装的 K3s，并让系统包管理器保留已安装版本；强制模式会重新安装系统软件包和 K3s。不会自动修改现有防火墙规则或删除网站数据。</p>`;
  } catch (error) { $('#modal-error').textContent = error.message; $('#modal-fields').innerHTML = ''; }
}
async function startEnvironmentInstall(serverId, mode) {
  if (mode === 'force' && !window.confirm('强制模式会重新安装已有组件。网站和数据库数据不会删除，但安装期间构建任务可能短暂受影响。确定继续吗？')) return;
  const job = await api(`/api/servers/${encodeURIComponent(serverId)}/environment-install`, { method: 'POST', body: JSON.stringify({ mode }) });
  $('#modal-title').textContent = '正在初始化服务器';
  const renderJob = current => { $('#modal-fields').innerHTML = `<div class="progress-wrap full"><div class="progress-meta"><strong>${escapeHTML(current.current || '准备中')}</strong><span>${current.progress}%</span></div><div class="progress-track"><i style="width:${current.progress}%"></i></div><small>完成 ${current.completed}/${current.total} 项</small></div><pre class="log-view">${escapeHTML((current.log || []).join('\n'))}</pre>`; $('#modal-error').textContent = current.error || ''; };
  renderJob(job);
  const poll = async () => { try { const current = await api(`/api/setup-jobs/${encodeURIComponent(job.id)}`); renderJob(current); if (current.status === 'running') return setTimeout(poll, 1200); if (current.status === 'completed') { toast('服务器环境初始化完成'); await refresh(); } else toast('环境初始化未完成，请查看错误'); } catch (error) { $('#modal-error').textContent = error.message; } };
  setTimeout(poll, 700);
}
async function refresh() {
  const [dashboard, servers, apps, databases, audit] = await Promise.all([api('/api/dashboard'), api('/api/servers'), api('/api/apps'), api('/api/databases'), api('/api/audit')]);
  Object.assign(state, { servers, apps, databases, audit: audit.events || [] }); renderDashboard(dashboard); renderLists(); navigate(location.hash.slice(1) || 'dashboard');
  refreshMonitoring();
}
function uptimeText(seconds = 0) { const days = Math.floor(seconds/86400), hours = Math.floor((seconds%86400)/3600); return days ? `${days} 天 ${hours} 小时` : `${hours} 小时`; }
function meter(label, value, detail) { const level = value >= 90 ? 'critical' : value >= 75 ? 'warning' : ''; return `<div class="monitor-meter ${level}"><div><span>${label}</span><strong>${value}%</strong></div><i><b style="width:${Math.min(100,value)}%"></b></i><small>${escapeHTML(detail)}</small></div>`; }
function renderMonitoring(items) { state.monitoring = Object.fromEntries(items.map(item => [item.serverId, item])); $('#monitoring-list').innerHTML = state.servers.length ? state.servers.map(server => { const m = state.monitoring[server.id]; if (!m || m.status === 'offline') return `<article class="monitor-card offline"><div class="card-top"><h4>${escapeHTML(server.name)}</h4><span class="badge offline">离线</span></div><p>${escapeHTML(m?.error || '无法读取监控数据')}</p></article>`; const podWarning = m.podsReady !== m.podsTotal; return `<article class="monitor-card"><div class="card-top"><div><h4>${escapeHTML(server.name)}</h4><p>负载 ${escapeHTML(m.load1)} · 已运行 ${uptimeText(m.uptimeSeconds)}</p></div><span class="badge online">在线</span></div>${meter('CPU',m.cpuPercent,`${server.cpu || '-'} 核心`)}${meter('内存',m.memoryPercent,`${m.memoryUsedMB} / ${m.memoryTotalMB} MB`)}${meter('磁盘',m.diskPercent,`${m.diskUsedGB} / ${m.diskTotalGB} GB`)}<div class="pod-health ${podWarning ? 'warning' : ''}"><span>K3s Pod</span><strong>${m.podsReady}/${m.podsTotal} 就绪</strong></div></article>`; }).join('') : '<div class="empty-state">尚未添加服务器</div>'; $('#monitoring-updated').textContent = `更新于 ${new Date().toLocaleTimeString('zh-CN')}`; renderDashboard({ servers: state.servers.length, onlineServers: state.servers.filter(s=>s.status==='online').length, apps: state.apps.length, runningApps: state.apps.filter(a=>a.status==='running').length, databases: state.databases.length, audit: state.audit }); renderLists(); }
async function refreshMonitoring() { try { renderMonitoring(await api('/api/monitoring')); } catch (error) { if (!String(error.message).includes('重新登录')) $('#monitoring-updated').textContent = `监控读取失败：${error.message}`; } }
setInterval(() => { if (!$('#app').classList.contains('hidden')) refreshMonitoring(); }, 30000);

const definitions = {
  server: { eyebrow: 'CONNECT', title: '添加服务器', endpoint: '/api/servers', fields: [
    ['name','名称','text','生产服务器'], ['host','IP 或主机名','text','192.0.2.10'], ['port','SSH 端口','number','22'], ['user','SSH 用户','text','root'], ['authType','SSH 登录方式','select','privateKey|密钥登录,password|密码登录'], ['privateKey','SSH 私钥','textarea','粘贴完整 OpenSSH 私钥','full','key-only'], ['password','SSH 密码','password','输入服务器登录密码','full','password-only'], ['description','备注','text','可选','full'] ] },
  app: { eyebrow: 'DEPLOY', title: '创建应用', endpoint: '/api/apps', fields: [
    ['name','应用名称','text','my-app'], ['serverId','目标服务器','server'], ['sourceType','源码类型','select','git|Git 仓库,upload|本地上传'], ['repository','Git 地址','text','https://github.com/...','full','git-only'], ['archive','源码压缩包','file','.zip,.tar.gz,.tgz','full','upload-only'], ['branch','分支','text','main','','git-only'], ['buildType','构建方式','select','auto|自动识别,dockerfile|Dockerfile,static|静态网站'], ['port','应用端口','number','8080'], ['autoDeploy','自动部署','checkbox','checked','',''], ['domain','绑定域名','text','app.example.com'], ['envText','环境变量','textarea','每行一个，例如：\nDATABASE_URL=...\nAPI_KEY=...','full'] ] },
  database: { eyebrow: 'DATA', title: '创建数据库', endpoint: '/api/databases', fields: [
    ['name','数据库名称','text','main-db'], ['serverId','目标服务器','server'], ['engine','数据库','select','postgresql|PostgreSQL,mysql|MySQL,redis|Redis'], ['version','版本','text','16'], ['storageGB','存储空间 GB','number','10'] ] }
};
function fieldHTML(field) {
  const [name,label,type,value,klass='',mode=''] = field; let control;
  if (type === 'server') control = `<select name="${name}" required><option value="">请选择</option>${state.servers.map(s => `<option value="${escapeHTML(s.id)}">${escapeHTML(s.name)}</option>`).join('')}</select>`;
  else if (type === 'select') control = `<select name="${name}">${value.split(',').map(v => { const [key,text]=v.split('|'); return `<option value="${key}">${text}</option>`; }).join('')}</select>`;
  else if (type === 'file') control = `<input name="${name}" type="file" accept=".zip,.tar.gz,.tgz">`;
  else if (type === 'checkbox') control = `<input name="${name}" type="checkbox" ${value === 'checked' ? 'checked' : ''}>`;
  else if (type === 'textarea') control = `<textarea name="${name}" placeholder="${escapeHTML(value)}" ${name === 'privateKey' ? 'required' : ''}></textarea>`;
  else control = `<input name="${name}" type="${type}" placeholder="${escapeHTML(value)}" ${['name','host'].includes(name) ? 'required' : ''}>`;
  return `<label class="${klass} ${mode}" data-mode="${mode}">${label}${control}</label>`;
}
function updateSourceFields() { const type = $('#modal-form [name="sourceType"]')?.value || 'git'; document.querySelectorAll('[data-mode="git-only"]').forEach(el => el.classList.toggle('hidden', type !== 'git')); document.querySelectorAll('[data-mode="upload-only"]').forEach(el => el.classList.toggle('hidden', type !== 'upload')); const archive = $('#modal-form [name="archive"]'); if (archive) archive.required = type === 'upload'; }
