async function openDatabaseBackups(id) { $('#modal-form').dataset.kind = ''; $('#modal-eyebrow').textContent = 'DATABASE BACKUPS'; $('#modal-title').textContent = '数据库备份与恢复'; $('#modal-fields').innerHTML = '<div class="setup-loading full"><span class="spinner"></span>正在读取备份记录…</div>'; $('#modal-error').textContent = ''; $('.modal-actions').classList.add('hidden'); if (!$('#modal').open) $('#modal').showModal(); try { const data = await api(`/api/databases/${encodeURIComponent(id)}/backups`); const items = [...(data.backups || [])].reverse(); $('#modal-title').textContent = `${data.database} · 备份与恢复`; $('#modal-fields').innerHTML = `<div class="backup-toolbar full"><div><strong>${items.length} 个备份</strong><small>备份过程不会停止数据库</small></div><button type="button" class="primary" data-db-backup-create="${escapeHTML(id)}">立即备份</button></div><div class="backup-list full">${items.length ? items.map(item => `<article><div><strong>${escapeHTML(item.filename)}</strong><small>${new Date(item.createdAt).toLocaleString('zh-CN')} · ${formatBytes(item.size)} · ${escapeHTML(item.reason || '备份')}</small></div><div><a class="secondary link-button" href="/api/databases/${encodeURIComponent(id)}/backups/${encodeURIComponent(item.id)}/download">下载</a><button type="button" class="danger-button" data-db-backup-restore="${escapeHTML(id)}" data-backup-id="${escapeHTML(item.id)}" data-database-name="${escapeHTML(data.database)}">恢复</button></div></article>`).join('') : '<div class="empty-state">尚无可用备份，请先点击“立即备份”</div>'}</div><p class="muted full">恢复前会自动再创建一份安全备份。恢复会覆盖当前数据库对象和数据，需要输入数据库名称确认。</p>`; } catch (error) { $('#modal-fields').innerHTML = ''; $('#modal-error').textContent = error.message; } }
function openAdoptedDomains(app) { const values = (app.domains || []).map(d => d.host).join('\n'); $('#modal-form').dataset.kind = `adopteddomains:${app.id}`; $('#modal-eyebrow').textContent = 'DOMAIN ROUTES'; $('#modal-title').textContent = `${app.name} · 编辑域名`; $('#modal-fields').innerHTML = `<label class="full">绑定域名（每行一个）<textarea name="domainsText" placeholder="app.example.com\nwww.example.com">${escapeHTML(values)}</textarea></label><p class="muted full">保存后会立即更新 Caddy 路由和 HTTPS。删除某一行即可解绑该域名；留空将解绑全部域名，但应用仍保持运行。</p>`; $('#modal-error').textContent = ''; $('.modal-actions').classList.remove('hidden'); $('#modal').showModal(); }
async function openAppHistory(id) { $('#modal-form').dataset.kind = ''; $('#modal-eyebrow').textContent = 'DEPLOYMENT HISTORY'; $('#modal-title').textContent = '部署版本与回滚'; $('#modal-fields').innerHTML = '<div class="setup-loading full"><span class="spinner"></span>正在读取部署历史…</div>'; $('#modal-error').textContent = ''; $('.modal-actions').classList.add('hidden'); if (!$('#modal').open) $('#modal').showModal(); try { const data = await api(`/api/apps/${encodeURIComponent(id)}/history`); const revisions = [...(data.revisions || [])].reverse(); $('#modal-fields').innerHTML = revisions.length ? `<div class="revision-list full">${revisions.map((r, index) => { const current = r.image === data.currentImage; return `<article><div><strong>${current ? '当前版本' : `历史版本 ${revisions.length-index}`}</strong><small>${new Date(r.deployedAt).toLocaleString('zh-CN')} · ${escapeHTML(r.reason || '部署')}</small><code>${escapeHTML(r.gitCommit ? r.gitCommit.slice(0,12) : r.image)}</code></div>${current || r.id === 'current' ? '<span class="badge running">运行中</span>' : `<button type="button" class="secondary" data-app-rollback="${escapeHTML(id)}" data-revision="${escapeHTML(r.id)}">回滚到此版本</button>`}</article>`; }).join('')}</div><p class="muted full">最多保留最近 12 个部署版本。回滚只切换应用镜像，不修改环境变量、域名和数据库。</p>` : '<div class="empty-state full">尚无部署历史；下次重新部署后会自动记录版本。</div>'; } catch (error) { $('#modal-fields').innerHTML = ''; $('#modal-error').textContent = error.message; } }
async function openDomainHealth(id) { $('#modal-form').dataset.kind = ''; $('#modal-eyebrow').textContent = 'DOMAIN & TLS HEALTH'; $('#modal-title').textContent = '正在检测域名'; $('#modal-fields').innerHTML = '<div class="setup-loading full"><span class="spinner"></span>正在检查 DNS、Caddy、HTTPS 和证书…</div>'; $('#modal-error').textContent = ''; $('.modal-actions').classList.add('hidden'); if (!$('#modal').open) $('#modal').showModal(); try { const data = await api(`/api/apps/${encodeURIComponent(id)}/domain-health`); $('#modal-title').textContent = `${data.app} · 域名状态`; $('#modal-fields').innerHTML = `<div class="domain-health-list full">${(data.domains || []).map(d => { const warning = d.caddyConfigured && d.https && d.daysRemaining <= 30; const healthy = d.caddyConfigured && d.https && d.daysRemaining > 30; return `<article class="${healthy ? 'healthy' : warning ? 'warning' : 'failed'}"><div class="domain-health-head"><div><strong>${escapeHTML(d.host)}</strong><small>${escapeHTML((d.dns || []).join(' · ') || '无 DNS 记录')}</small></div><span>${healthy ? '✓ 正常' : warning ? '即将到期' : '需要处理'}</span></div><dl><div><dt>Caddy 路由</dt><dd>${d.caddyConfigured ? '已配置' : '未配置'}</dd></div><div><dt>HTTPS</dt><dd>${d.https ? `HTTP ${d.httpStatus}` : '连接失败'}</dd></div><div><dt>证书颁发者</dt><dd>${escapeHTML(d.certIssuer || '-')}</dd></div><div><dt>证书有效期</dt><dd>${d.certExpiresAt ? `${new Date(d.certExpiresAt).toLocaleDateString('zh-CN')}（剩余 ${d.daysRemaining} 天）` : '-'}</dd></div></dl>${d.error ? `<p class="error">${escapeHTML(d.error)}</p>` : ''}</article>`; }).join('')}</div><p class="muted full">DNS 经过 Cloudflare 代理时会显示 Cloudflare 公网 IP，属于正常现象。证书少于 30 天会提示关注。</p>`; } catch (error) { $('#modal-fields').innerHTML = ''; $('#modal-error').textContent = error.message; } }
let runtimeLogTimer = null;
function stopRuntimeLogs() { if (runtimeLogTimer) clearTimeout(runtimeLogTimer); runtimeLogTimer = null; }
async function openRuntimeLogs(id) { stopRuntimeLogs(); $('#modal-form').dataset.kind = ''; $('#modal-eyebrow').textContent = 'LIVE APPLICATION LOG'; $('#modal-title').textContent = '应用运行日志'; $('#modal-fields').innerHTML = '<pre id="runtime-log-output" class="log-view">正在连接运行中的容器…</pre><p class="muted full">每 3 秒自动刷新最近 500 行，关闭窗口即可停止。</p>'; $('#modal-error').textContent = ''; $('.modal-actions').classList.add('hidden'); if (!$('#modal').open) $('#modal').showModal(); const poll = async () => { if (!$('#modal').open || !$('#runtime-log-output')) return stopRuntimeLogs(); try { const data = await api(`/api/apps/${encodeURIComponent(id)}/runtime-logs`); const output = $('#runtime-log-output'); if (output) { output.textContent = data.logs || '当前没有日志输出'; output.scrollTop = output.scrollHeight; } $('#modal-error').textContent = ''; } catch (error) { $('#modal-error').textContent = error.message; } runtimeLogTimer = setTimeout(poll, 3000); }; await poll(); }
